/*
 * A259598  Number of representations of n as u(h) + v(k), where u = A000201
 *          (lower Wythoff numbers), v = A001950 (upper Wythoff numbers),
 *          h>=1, k>=1.
 * https://oeis.org/A259598
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, changed
 * Formula:   a(n) = number of representations n = u(h) + v(k) where u(h) =
 *            floor(h*φ) (lower Wythoff) and v(k) = floor(k*φ²) (upper
 *            Wythoff), h,k ≥ 1. The sequences are generated by Beatty’s
 *            construction: the next u is the smallest integer not already
 *            used as a u or v; v(k) = u(k) + k. This leads to an O(n) a...
 * Range:     u8 n <= 77, u16 n <= 77, u32 n <= 77, u64 n <= 77, u128 n <= 77,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* a(1) is the first term of the sequence.  Behaviour for n<1 is irrelevant. */
    if (n < 1) return 0;

    /* Allocate tables for indices 0..n (index 0 unused) */
    size_t cap = (size_t)(n + 1);
    uint8_t *usedAll = (uint8_t*)calloc(cap, sizeof(uint8_t));
    if (!usedAll) return 0;
    uint8_t *usedU   = (uint8_t*)calloc(cap, sizeof(uint8_t));
    if (!usedU) { free(usedAll); return 0; }

    /* Temporary storage for the lower Wythoff numbers (size n is plenty) */
    seq_t *u = (seq_t*)malloc(cap * sizeof(seq_t));
    if (!u) { free(usedAll); free(usedU); return 0; }

    idx_t k = 0;  /* count of u values found, starts at 0 */
    idx_t m = 1;  /* candidate integer for u */
    while (m <= n) {
        if (!usedAll[m]) {  /* m is the next lower Wythoff number */
            k++;
            u[k] = (seq_t)m;
            usedAll[m] = 1;
            usedU[m]   = 1;

            idx_t v = m + k;   /* v(k) = u(k) + k */
            if (v <= n)
                usedAll[v] = 1;
        }
        m++;
    }

    /* Count representations of n as u(h)+v(k) */
    seq_t count = 0;
    for (idx_t i = 1; i <= k; ++i) {
        seq_t v = u[i] + (seq_t)i;          /* v(k) */
        if (v > (seq_t)n) continue;         /* sum too large for this n */
        idx_t target = n - (idx_t)v;        /* required lower Wythoff number */
        if (target >= 1 && usedU[target])
            count++;
    }

    /* Clean up */
    free(u);
    free(usedU);
    free(usedAll);

    return count;
}
